// ================= static config =================
var IDEAL_CYCLE_SEC = 12;   // per-piece ideal cycle time (seconds)
var TZ_OFFSET_MIN   = 330;  // IST = UTC+5:30

// ================= helpers =================
// Enrichment node returns values with literal quotes baked in, e.g. "\"Running\"".
// Strip them before comparing or parsing.
function str(v, dflt) {
    if (v === null || v === undefined || v === "") return dflt;
    var s = String(v).replace(/^"|"$/g, '');
    return s === "" ? dflt : s;
}


function num(v, dflt) {
    if (v === null || v === undefined || v === "")
        return dflt;

    v = String(v).replace(/^"|"$/g, '');

    var n = Number(v);

    return isNaN(n) ? dflt : n;
}

var now = num(metadata.ts, new Date().getTime());

// ================= determine current shift =================
// Shifts (local time): 08:00-16:00 = shift 2, 16:00-24:00 = shift 3, 00:00-08:00 = shift 1
var localMs       = now + TZ_OFFSET_MIN * 60000;
var localMidnight = localMs - (localMs % 86400000);
var hourOfDay     = (localMs - localMidnight) / 3600000;

var shiftStartHour;
var shiftNo;
var plannedQty;
if (hourOfDay < 8) {
    shiftStartHour = 0;
    shiftNo = 1;
    plannedQty = Number(metadata.ss_shift1_planned);
} else if (hourOfDay < 16) {
    shiftStartHour = 8;
    shiftNo = 2;
    plannedQty = Number(metadata.ss_shift2_planned);
} else {
    shiftStartHour = 16;
    shiftNo = 3;
    plannedQty = Number(metadata.ss_shift3_planned);
}

// convert the local shift-start back to a UTC epoch value
var shiftStartUtc = localMidnight + shiftStartHour * 3600000 - TZ_OFFSET_MIN * 60000;
shiftStartUtc = Math.round(shiftStartUtc);

// ================= read back previous shift record =================
var prevShiftStart = num(metadata.shift_start, 0);
var isNewShift = (Math.round(prevShiftStart) !== shiftStartUtc);

var lastState   = str(metadata.last_state, "idle");
var lastStateTs = num(metadata.last_state_ts, 0);

var accOnline  = isNewShift ? 0 : num(metadata.total_online_time_min, 0);
var accOffline = isNewShift ? 0 : num(metadata.total_offline_time_min, 0);

// ================= counts (DELTA model) =================
// msg.good_count / msg.reject_count = produced SINCE THE LAST MESSAGE
var deltaGood   = num(msg.good_count, 0);
var deltaReject = num(msg.reject_count, 0);

var prevGood   = isNewShift ? 0 : num(metadata.total_good_count, 0);
var prevReject = isNewShift ? 0 : num(metadata.total_reject_count, 0);

var goodCount   = prevGood + deltaGood;
var rejectCount = prevReject + deltaReject;

// ================= accumulate time in the PREVIOUS state =================
var fromTs = lastStateTs;
if (fromTs < shiftStartUtc) {
    fromTs = shiftStartUtc;   // clip: don't count time that belongs to the previous shift
}
if (lastStateTs > 0 && now > fromTs) {
    var deltaMin = (now - fromTs) / 60000;
    if (lastState.toLowerCase() === "running") {
        accOnline = accOnline + deltaMin;
    } else {
        accOffline = accOffline + deltaMin;
    }
}

// payload key is machine_status
var currentState = str(msg.machine_status, lastState);

// ================= OEE =================
var totalCount = goodCount + rejectCount;

// planned time = elapsed minutes since shift start (no break subtracted)
var plannedTime = (now - shiftStartUtc) / 60000;

var availability = plannedTime > 0 ? (accOnline / plannedTime) : 0;
if (availability > 1) availability = 1;

var idealRatePerMin = IDEAL_CYCLE_SEC > 0 ? (60 / IDEAL_CYCLE_SEC) : 0;
var performance = 0;
if (accOnline > 0 && idealRatePerMin > 0) {
    performance = totalCount / (idealRatePerMin * accOnline);
}
if (performance > 1) performance = 1;

var quality = totalCount > 0 ? (goodCount / totalCount) : 0;

var oee = availability * performance * quality;


// ================= output =================
var out = {
    total_online_time_min:  Math.round(accOnline * 100) / 100,
    total_offline_time_min: Math.round(accOffline * 100) / 100,
    total_good_count:   goodCount,
    total_reject_count: rejectCount,
    availability: Math.round(availability * 10000) / 100,
    performance:  Math.round(performance  * 10000) / 100,
    quality:      Math.round(quality      * 10000) / 100,
    OEE:          Math.round(oee          * 10000) / 100,
    shift_no:      shiftNo,
    shift_start:   shiftStartUtc,
    last_state:    currentState,
    last_state_ts: now,
    planned: plannedQty
};

// ---------- Daily summary record (00:00 timestamp) ----------

// Midnight timestamp (UTC)
var dayStartUtc = localMidnight - TZ_OFFSET_MIN * 60000;
dayStartUtc = Math.round(dayStartUtc);

// Create only the current shift key
var dailyMsg = {};

if (shiftNo === 1) {
    dailyMsg.shift1_oee = out.OEE;
} else if (shiftNo === 2) {
    dailyMsg.shift2_oee = out.OEE;
} else {
    dailyMsg.shift3_oee = out.OEE;
}

// Message 1 → Shift record
var shiftMetadata = Object.assign({}, metadata);
shiftMetadata.ts = String(shiftStartUtc);

// Message 2 → Daily record
var dayMetadata = Object.assign({}, metadata);
dayMetadata.ts = String(dayStartUtc);

return [
    {
        msg: out,
        metadata: shiftMetadata,
        msgType: msgType
    },
    {
        msg: dailyMsg,
        metadata: dayMetadata,
        msgType: msgType
    }
];
